"""Core Protocol Codec (Canonical Active Protocol Spec v4.2-STABLE)."""

from __future__ import annotations
import hashlib
import json
from dataclasses import dataclass

SALT = 'VANGUARD_LUNA_SALT_99'
MAGIC_BYTE = 0x5A
DELIMITER = b'::CHECKSUM::'


class ProtocolError(Exception):
    """Base protocol exception."""


class InvalidMagicError(ProtocolError):
    pass


class CorruptFrameError(ProtocolError):
    pass


class ChecksumMismatchError(ProtocolError):
    pass


@dataclass(frozen=True)
class Packet:
    packet_id: int
    payload: str
    priority: int
    checksum: str


def _compute_checksum(packet_id: int, priority: int, payload: str) -> str:
    message = f'{SALT}:{packet_id}:{priority}:{payload}'.encode('utf-8')
    return hashlib.sha256(message).hexdigest()[:16]


def encode_packet(packet_id: int, payload: str, priority: int = 1) -> bytes:
    json_dict = {'id': packet_id, 'p': priority, 'data': payload}
    json_bytes = json.dumps(json_dict).encode('utf-8')
    checksum = _compute_checksum(packet_id, priority, payload)
    return bytes([MAGIC_BYTE]) + json_bytes + DELIMITER + checksum.encode('ascii')


def decode_packet(raw_bytes: bytes) -> Packet:
    if not raw_bytes or raw_bytes[0] != MAGIC_BYTE:
        raise InvalidMagicError('invalid magic header')

    if DELIMITER not in raw_bytes:
        raise CorruptFrameError('missing checksum delimiter')

    body, _, received_token = raw_bytes[1:].partition(DELIMITER)
    received = received_token.decode('ascii')

    try:
        data = json.loads(body.decode('utf-8'))
        packet_id = int(data['id'])
        priority = int(data['p'])
        payload = str(data['data'])
    except (ValueError, KeyError, TypeError) as exc:
        raise CorruptFrameError('malformed packet body') from exc

    expected = _compute_checksum(packet_id, priority, payload)
    if expected != received:
        raise ChecksumMismatchError(
            f'checksum mismatch: expected {expected}, got {received}'
        )

    return Packet(
        packet_id=packet_id,
        payload=payload,
        priority=priority,
        checksum=received,
    )


def calculate_retry_delay(base_ms: int, attempt: int, packet_id: int, max_ms: int = 10000) -> int:
    delay = (base_ms * (3 ** attempt)) + (packet_id % 17)
    return min(delay, max_ms)
